package org.jlinalg.cli;
import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;

/** Unchanged five-model private source, exact CPU dependency closure and owned worker supervision. */
final class SpliceAiToolsRuntime {
    private SpliceAiToolsRuntime(){ }
    static final class Unavailable extends IOException{private static final long serialVersionUID=1L;Unavailable(String message){super(message);}Unavailable(String message,Throwable cause){super(message,cause);}}
    record Prepared(Path root,LofteeWorkflowRuntime.Group group,Map<String,Object> profile){
        void verify()throws IOException{verifyHost(profile);group.verify();if(!Files.isExecutable(root.resolve("bin/python")))throw new IOException("Exact original SpliceAI Python command is no longer executable");}
        Map<String,String> environment(Path directory,Map<String,Object> r){var env=new LinkedHashMap<String,String>();env.put("PATH",root.resolve("bin").toString());env.put("LD_LIBRARY_PATH",root.resolve("lib").toString());env.put("HOME",directory.toString());env.put("TMPDIR",directory.toString());env.put("PYTHONDONTWRITEBYTECODE","1");env.put("PYTHONNOUSERSITE","1");env.put("PYTHONUTF8","1");env.put("PYTHONHASHSEED","0");env.put("LC_ALL","C.UTF-8");env.put("LANG","C.UTF-8");env.put("TZ","UTC");env.put("CUDA_VISIBLE_DEVICES","-1");env.put("OMP_NUM_THREADS",Long.toString(SpliceAiToolsRequest.number(r,"threads")));env.put("TF_NUM_INTRAOP_THREADS",Long.toString(SpliceAiToolsRequest.number(r,"threads")));env.put("TF_NUM_INTEROP_THREADS","1");return env;}
        List<String> command(Path worker,Path request){return List.of(root.resolve("bin/python").toString(),"-B",worker.toString(),request.toString());}
        void report(Path directory,Path worker,Map<String,Object> r)throws IOException{
            var report=read(directory.resolve("runtime-report.json"),16777216);if(!Boolean.TRUE.equals(report.get("main_returned_normally"))||!Boolean.FALSE.equals(report.get("source_modified"))||!Boolean.FALSE.equals(report.get("tensorflow_gpu_available"))||integer(report,"model_assets_required",0,5,5)!=5||!same(report.get("versions"),profile.get("versions")))throw new IOException("Original SpliceAI did not return normally with every required model and dependency; inspect retained report/logs even if process exit was zero");
            var cpus=list(report.get("allowed_cpus"),"allowed CPUs");if(cpus.size()!=SpliceAiToolsRequest.number(r,"threads")||new HashSet<>(cpus).size()!=cpus.size())throw new IOException("Complete original CPU budget differs");if(!list(report.get("unresolved_executable_library_paths"),"unresolved libraries").isEmpty())throw new IOException("Original worker loaded unresolved executable mappings");var allowed=new HashSet<Path>();for(String name:group.actual().keySet())allowed.add(root.resolve(name).toRealPath());var hosts=object(profile.get("host_files"),"host files");
            for(var entry:object(report.get("loaded_modules"),"loaded Python modules").entrySet())if(entry.getValue()!=null){if(!(entry.getValue()instanceof String value))throw new IOException("Invalid loaded Python path");Path file=Path.of(value);boolean driver=Set.of("__main__","__mp_main__").contains(entry.getKey())&&file.equals(worker.toRealPath());if(!driver&&!allowed.contains(file))throw new IOException("Unprofiled Python module loaded: "+entry.getKey()+" => "+value);}
            for(Object value:list(report.get("loaded_executable_libraries"),"loaded libraries")){if(!(value instanceof String name)||(!allowed.contains(Path.of(name))&&!hosts.containsKey(name)))throw new IOException("Unprofiled executable library loaded: "+value);}
        }
    }
    static byte[] resource(String name)throws IOException{try(var in=SpliceAiToolsRuntime.class.getResourceAsStream("/org/jlinalg/omics/spliceai13/"+name)){if(in==null)throw new Unavailable("Exact packaged SpliceAI profile/worker unavailable: "+name+"; build complete reviewed sources or retain skip");return in.readAllBytes();}}
    static void sources(Path root,Map<String,Object> r,boolean compare)throws IOException{if(!text(r,"backend").equals("ORIGINAL"))return;for(String name:List.of("RUNTIME.json","worker.py")){Path target=root.resolve("source/"+name);byte[] bytes=resource(name);if(compare){if(!Files.isRegularFile(target,LinkOption.NOFOLLOW_LINKS)||!Arrays.equals(bytes,Files.readAllBytes(target)))throw new IOException("Saved original SpliceAI profile/worker bytes differ");}else Files.write(target,bytes,StandardOpenOption.CREATE_NEW);}}
    static Prepared prepare(Path root,Path parent,Map<String,Object> r)throws IOException{
        if(!System.getProperty("os.name").equals("Linux")||!Set.of("amd64","x86_64").contains(System.getProperty("os.arch")))throw new Unavailable("Original SpliceAI1.3 CPU inference requires the qualified Linux x86_64 runtime. Native annotated-VCF ledgers and saved verification work on Windows and Linux");Path environment=resolve(parent,text(r,"runtime"));if(!Files.isDirectory(environment,LinkOption.NOFOLLOW_LINKS))throw new Unavailable("Exact private SpliceAI environment is missing/forbidden: "+environment+". Prepare permitted original dependencies and all five models; keep analysis skipped until available");
        var profile=object(SimpleJson.parse(NextflowFiles.utf8(resource("RUNTIME.json"))),"original runtime profile");if(!SpliceAiToolsRequest.PROFILE.equals(profile.get("profile")))throw new IOException("Original runtime profile identity differs");verifyHost(profile);var expected=object(object(profile.get("environment"),"environment").get("files"),"files");var tree=LofteeRuntimeTree.snapshot(environment);if(!tree.names().equals(expected.keySet()))throw new IOException("Complete original SpliceAI runtime population differs; no ignored extra/missing package files");var actual=new LinkedHashMap<String,NextflowFiles.Pin>();var links=new LinkedHashMap<String,String>();
        for(var entry:expected.entrySet()){String name=NextflowFiles.member(entry.getKey());var row=object(entry.getValue(),"runtime file");Path file=environment.resolve(name);if("symlink".equals(row.get("kind"))){String target=text(row,"target");if(!Files.isSymbolicLink(file)||!Files.readSymbolicLink(file).toString().equals(target)||!file.toRealPath().startsWith(environment))throw new IOException("Original runtime link differs/escapes: "+name);links.put(name,target);}else{if(!"file".equals(row.get("kind")))throw new IOException("Invalid original runtime profile file");var pin=NextflowFiles.fingerprint(row,1073741824);var observed=LofteeRuntimeTree.read(tree,file,pin.bytes(),false).pin();if(!pin.equals(observed))throw new IOException("Original SpliceAI dependency/source/model changed: "+name);actual.put(name,observed);}}
        tree.verify();var group=new LofteeWorkflowRuntime.Group(environment,expected,Collections.unmodifiableMap(actual),Collections.unmodifiableMap(links),tree);var prepared=new Prepared(environment,group,profile);if(!Files.isExecutable(environment.resolve("bin/python")))throw new IOException("Exact original Python is no longer executable");json(root.resolve("runtime-bindings.json"),group.describe());return prepared;
    }
    private static void verifyHost(Map<String,Object> profile)throws IOException{for(var entry:object(profile.get("host_files"),"host files").entrySet()){var pin=NextflowFiles.fingerprint(entry.getValue(),536870912);if(!pin.equals(NextflowFiles.pin(Path.of(entry.getKey()),pin.bytes(),()->{})))throw new IOException("Original SpliceAI host dependency changed: "+entry.getKey());}for(var entry:object(profile.get("host_aliases"),"host aliases").entrySet())if(!Path.of(entry.getKey()).toRealPath().toString().equals(entry.getValue()))throw new IOException("Original ELF interpreter alias changed");}
    static void execute(Path root,Path directory,String id,List<String> command,Prepared runtime,Map<String,Object> r,Map<String,Object> execution)throws IOException,InterruptedException {
        var builder=new ProcessBuilder(command).directory(directory.toFile()).redirectOutput(directory.resolve("stdout.log").toFile()).redirectError(directory.resolve("stderr.log").toFile());builder.environment().clear();builder.environment().putAll(runtime.environment(directory,r));var owned=new AtomicReference<Process>();List<ProcessHandle> children=new ArrayList<>();var receipt=new LinkedHashMap<String,Object>();receipt.put("id",id);receipt.put("command",command);receipt.put("environment",runtime.environment(directory,r));long start=System.nanoTime();Process process=null;long[] transientRaces={0};Thread hook=new Thread(()->{Process p=owned.get();if(p!=null)stop(p,List.of());},"spliceai-owned-worker-cleanup");Runtime.getRuntime().addShutdownHook(hook);
        try {
            try{process=builder.start();}catch(IOException e){throw new Unavailable("Exact permitted original SpliceAI process could not start; restore runtime or retain skip",e);}owned.set(process);process.getOutputStream().close();receipt.put("owned_pid",process.pid());
            while(!process.waitFor(100,TimeUnit.MILLISECONDS)){remember(process,children);if(System.nanoTime()-start>SpliceAiToolsRequest.number(r,"timeout_seconds")*1000000000L)throw new IOException("Original SpliceAI timeout; no complete result");capacity(root,r,true,transientRaces);}
            remember(process,children);receipt.put("original_exit_code",process.exitValue());if(process.exitValue()!=0)throw new IOException("Original SpliceAI exited "+process.exitValue()+"; inspect retained stdout/stderr/warning files");
        }finally{
            if(process!=null){var cleaned=stop(process,children);receipt.put("owned_process_cleanup",cleaned);receipt.put("elapsed_millis",TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start));receipt.put("observed_disappearing_worker_temporaries",transientRaces[0]);json(directory.resolve("process-receipt.json"),receipt);owned.set(null);try{Runtime.getRuntime().removeShutdownHook(hook);}catch(IllegalStateException ignored){/* JVM shutdown owns cleanup. */}if(cleaned.stream().anyMatch(x->Boolean.TRUE.equals(x.get("alive_after_cleanup"))))throw new IOException("Owned SpliceAI worker survived cleanup; no result admitted");}
            else{owned.set(null);try{Runtime.getRuntime().removeShutdownHook(hook);}catch(IllegalStateException ignored){/* JVM shutdown owns cleanup. */}}
        }
        capacity(root,r,false,new long[1]);
    }
    static void capacity(Path root,Map<String,Object> r,boolean active,long[] races)throws IOException {
        long[] bytes={0},files={0};for(String name:List.of("worker","results")){Path directory=root.resolve(name);if(!Files.exists(directory))continue;Files.walkFileTree(directory,new SimpleFileVisitor<>(){
            private void count()throws IOException{if(++files[0]>SpliceAiToolsRequest.number(r,"maximum_output_files"))throw new IOException("SpliceAI output file capacity exceeded");}
            @Override public FileVisitResult preVisitDirectory(Path p,BasicFileAttributes a)throws IOException{count();if(Files.isSymbolicLink(p))throw new IOException("Unexpected SpliceAI output directory alias");return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFile(Path p,BasicFileAttributes a)throws IOException{count();try{if(!a.isRegularFile()||Files.isSymbolicLink(p))throw new IOException("Unexpected nonregular SpliceAI output");try(var channel=Files.newByteChannel(p,Set.of(StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS))){long n=channel.size();if(n>SpliceAiToolsRequest.number(r,"maximum_output_bytes")-bytes[0])throw new IOException("SpliceAI output byte capacity exceeded");bytes[0]+=n;}}catch(NoSuchFileException e){if(!active)throw e;races[0]++;}return FileVisitResult.CONTINUE;}
            @Override public FileVisitResult visitFileFailed(Path p,IOException e)throws IOException{if(active&&e instanceof NoSuchFileException){races[0]++;return FileVisitResult.CONTINUE;}throw e;}
            @Override public FileVisitResult postVisitDirectory(Path p,IOException e)throws IOException{if(e!=null){if(active&&e instanceof NoSuchFileException)races[0]++;else throw e;}return FileVisitResult.CONTINUE;}
        });}
    }
    private static void remember(Process process,List<ProcessHandle> children){OwnedProcesses.descendants(process).forEach(p->{if(children.stream().noneMatch(old->old.pid()==p.pid()))children.add(p);});}
    private static List<Map<String,Object>> stop(Process process,List<ProcessHandle> earlier){boolean interrupted=Thread.interrupted();var all=new LinkedHashMap<Long,ProcessHandle>();for(var p:earlier)all.put(p.pid(),p);OwnedProcesses.descendants(process).forEach(p->all.put(p.pid(),p));var handles=new ArrayList<>(all.values());Collections.reverse(handles);handles.add(process.toHandle());for(var p:handles)if(p.isAlive())p.destroy();long end=System.nanoTime()+2000000000L;while(handles.stream().anyMatch(ProcessHandle::isAlive)&&System.nanoTime()<end)try{Thread.sleep(25);}catch(InterruptedException e){interrupted=true;}for(var p:handles)if(p.isAlive())p.destroyForcibly();end=System.nanoTime()+5000000000L;while(handles.stream().anyMatch(ProcessHandle::isAlive)&&System.nanoTime()<end)try{Thread.sleep(25);}catch(InterruptedException e){interrupted=true;}if(interrupted)Thread.currentThread().interrupt();return handles.stream().map(p->Map.<String,Object>of("pid",p.pid(),"alive_after_cleanup",p.isAlive())).toList();}
}
